const STAGE="init";
// Executed in an n8n Code node. The generator supplies the chosen STAGE.
const rows = $input.all();
if (STAGE === 'init') {
  const c = typeof rows[0].json.context === 'string' ? JSON.parse(rows[0].json.context) : rows[0].json.context;
  if (!c.users.length) return [];
  const now = new Date();
  const until = new Date(now.getTime()+6*3600000);
  const end = new Date(until.getTime()+30*60000);
  return [{json:{...c,now:now.toISOString(),until:until.toISOString(),end:end.toISOString(),
    from:new Date(now.getTime()-86400000).toISOString().slice(0,10),to:new Date(end.getTime()+86400000).toISOString().slice(0,10),
    year:now.getUTCFullYear(),end_year:end.getUTCFullYear(),events:[],warnings:[]}}];
}
const source = {football:'Football needed?',basketball:'NBA needed?',f1:'F1 needed?',next:'Next year needed?'};
if (source[STAGE]) {
  const c = JSON.parse(JSON.stringify($(source[STAGE]).first().json));
  const r = rows[0].json;
  if (STAGE === 'football') {
    if (r.error || !Array.isArray(r.matches)) {
      c.warnings.push('Football calendar unavailable; inspect credentials and rerun the planner.');
      return [{json:c}];
    }
    for (const m of r.matches) if (['SCHEDULED','TIMED'].includes(m.status) && m.homeTeam?.id && m.awayTeam?.id)
      c.events.push({event_id:'football-'+m.id,provider_id:String(m.id),sport:'football',at:m.utcDate,
        home_id:m.homeTeam.id,away_id:m.awayTeam.id,home:m.homeTeam.name,away:m.awayTeam.name,
        title:m.homeTeam.name+' vs '+m.awayTeam.name,competition:m.competition?.name||'Football',
        participants:[m.homeTeam.name,m.homeTeam.shortName,m.homeTeam.tla,m.awayTeam.name,m.awayTeam.shortName,m.awayTeam.tla].filter(Boolean)});
  } else if (STAGE === 'basketball') {
    for (const row of rows) {
      const body=row.json.body||row.json;
      if (row.json.error || body.error || !Array.isArray(body.data)) {
        c.warnings.push('BALLDONTLIE calendar unavailable. Check credentials or rate limit, then rerun the planner.');
        continue;
      }
      for (const g of body.data) {
        if (g.postponed || (g.status_state && g.status_state!=='scheduled') || /final|postpon|cancel|suspend|abandon|delay/i.test(g.status||'')) continue;
        if (!g.status_state && Number(g.period||0)!==0) continue;
        if (!g.home_team?.id || !g.visitor_team?.id) continue;
        c.events.push({event_id:'basketball-bdl-'+g.id,provider_id:String(g.id),sport:'basketball',at:g.datetime,
          home_id:g.home_team.id,away_id:g.visitor_team.id,home:g.home_team.full_name,away:g.visitor_team.full_name,
          title:g.home_team.full_name+' vs '+g.visitor_team.full_name,competition:'NBA',
          participants:[g.home_team.full_name,g.home_team.name,g.home_team.abbreviation,g.visitor_team.full_name,g.visitor_team.name,g.visitor_team.abbreviation].filter(Boolean)});
      }
    }
    const last=rows.at(-1).json;
    if ((last.body||last).meta?.next_cursor!=null) c.warnings.push('NBA calendar pagination incomplete; rerun after fixing pagination.');
  } else {
    const races=r.MRData?.RaceTable?.Races;
    if (r.error || !Array.isArray(races)) {
      c.warnings.push('Jolpica F1 schedule unavailable; rerun the planner later.');
      return [{json:c}];
    }
    for (const race of races) for (const [session,s] of [['Race',race],['Qualifying',race.Qualifying]]) {
      if (!s?.time || !s.date) continue;
      c.events.push({event_id:`f1-${race.season}-${race.round}-${session}`,sport:'f1',season:String(race.season),round:String(race.round),session,
        at:s.date+'T'+s.time,title:race.raceName+' — '+session,competition:'Formula 1',participants:[],
        circuit:race.Circuit?.circuitName||'',location:race.Circuit?.Location?.locality||''});
    }
  }
  return [{json:c}];
}
if (STAGE === 'jobs') {
  const c=rows[0].json, now=Date.now(), until=Date.parse(c.until), jobs=[], seen=new Set();
  const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const follows=(u,e)=>u.prefs.some(p=>p.sport===e.sport && (e.sport==='f1'||[...(p.aliases||[]),p.label].some(a=>e.participants.some(n=>norm(n)===norm(a)))));
  for (const e of c.events) {
    const at=Date.parse(e.at);
    if (!Number.isFinite(at) || !String(e.at).includes('T') || !e.title || seen.has(e.event_id)) continue;
    seen.add(e.event_id);
    for (const kind of ['preview','start']) {
      const due=at-(kind==='preview'?30*60000:0);
      if (due<now-(kind==='preview'?5:3)*60000 || due>=until) continue;
      if (!c.users.some(u=>(kind==='preview'?u.previews_enabled:u.reminders_enabled) && follows(u,e))) continue;
      jobs.push({...e,kind,due_at:new Date(due).toISOString()});
    }
  }
  jobs.sort((a,b)=>a.due_at.localeCompare(b.due_at));
  return [{json:{jobs,warnings:c.warnings||[]}}];
}
throw new Error('Unknown planner stage');

